//-----------------
//let in Processing(Java)
//-----------------
let Unit;
let Counter;
let MX, MY;

function setup() {
  createCanvas(windowWidth, windowHeight);
  Unit=128; // largest size of a square
  Counter=0;
  stroke(0);
	noFill();
}

function draw() {
  background(255);
  Counter+=0.002;
  MX=(window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX)))*0.001;
  MY=(window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY)))*0.001;
  for (j=0; j<height; j+=Unit) {
    for (i=0; i<width; i+=Unit) {
      DrawRect(i, j, Unit);
    }
  }
}

function DrawRect(x, y, size) {
  let cx=x+size/2; // center in the square for noise
  let cy=y+size/2;
  let n=noise(cx/width-MX, cy/height-MY, mag(cx, cy)/height-Counter);
  let threshold=map(size, Unit, 4, 0.18, 0.05 );
  if (abs(n-0.5)>threshold) {
    rect(x, y, size, size);
  } else {
    size=size/2;
    if (size>=4) { // smallest size of a square = 4pixels
      DrawRect(x     , y     , size);
      DrawRect(x+size, y     , size);
      DrawRect(x     , y+size, size);
      DrawRect(x+size, y+size, size);
    }
  }
}


